#!/usr/bin/env python3
"""Render and link the small native adapters around shared assets."""

import argparse
import json
import os
import pathlib
import re
import shlex
import sys
import tomllib


MARKERS = (
    "# Generated by my-harness-config bootstrap.",
    "# Generated by my-codex-config bootstrap.",
)
POLICY_START = "<!-- BEGIN my-harness-config policy -->"
POLICY_END = "<!-- END my-harness-config policy -->"
LEGACY_POLICY_MARKER = MARKERS[1]
HOOK_OWNER = "codex-command-dispatch.mjs"
GUARD_OWNER = "agent-model-guard.py"
OPUS_OWNER = "opus-guard.py"
UI_OWNER = "ui-open-reminder.py"
COMPACT_WINDOW = 300000
LOCAL_TZ = "Europe/Madrid"
# Skills Claude Code syncs from claude.ai or bundles that the user keeps off. Synced ones need the
# `anthropic-skills:` key (a bare name is skipped when taken); plugin skills cannot be reached this way.
SKILLS_OFF = (
    "anthropic-skills:skill-creator",
    "anthropic-skills:agent-prompt-writing",
    "anthropic-skills:deep-research",
    "anthropic-skills:computer-use",
    "anthropic-skills:built-in-browser",
    "anthropic-skills:morning",
    "anthropic-skills:import-memory",
    "anthropic-skills:general-instructions",
    "simplify",
    "init",
    "artifact-diagramming",
    "artifact-design",
    "artifact-capabilities",
)


def backup(target: pathlib.Path, backup_root: pathlib.Path) -> None:
    try:
        relative = target.relative_to(pathlib.Path.home())
    except ValueError:
        relative = pathlib.Path(target.name)
    destination = backup_root / relative
    index = 1
    while destination.exists() or destination.is_symlink():
        destination = backup_root / f"{relative}.{index}"
        index += 1
    backup_root.mkdir(parents=True, exist_ok=True, mode=0o700)
    os.chmod(backup_root, 0o700)
    destination.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
    os.replace(target, destination)


def ensure_directory(path: pathlib.Path, backup_root: pathlib.Path) -> pathlib.Path:
    if path.is_symlink():
        if path.exists() and path.is_dir():
            return path
        backup(path, backup_root)
    elif path.exists() and not path.is_dir():
        backup(path, backup_root)
    path.mkdir(parents=True, exist_ok=True)
    return path


def prune_dangling(target: pathlib.Path, roots: list[pathlib.Path], backup_root: pathlib.Path) -> None:
    """Back up dangling links into a source this repository manages; every other entry stays."""
    # A missing portable clone is not a source yet, so links into it are not ours to judge.
    managed = {path for root in roots if root.is_dir() for path in (root.absolute(), root.resolve())}
    for entry in target.iterdir():
        if not entry.is_symlink() or os.path.exists(entry):
            continue
        # The OS resolves a relative link from the physical folder it sits in, symlinks before `..`.
        destination = pathlib.Path(os.path.realpath(entry.parent / os.readlink(entry)))
        if any(destination.is_relative_to(root) for root in managed):
            backup(entry, backup_root)


def install_skills(args: argparse.Namespace) -> None:
    target = ensure_directory(pathlib.Path(args.target), pathlib.Path(args.backup))
    roots = [pathlib.Path(args.source), *(pathlib.Path(value) for value in args.portable)]
    skills: dict[str, pathlib.Path] = {}
    for root in roots:
        if not root.is_dir():
            continue
        if (root / "SKILL.md").is_file():
            name = "excalidraw" if root.name == "skill" else root.name
            skills[name] = root.resolve()
            continue
        for directory in root.iterdir():
            if not (directory / "SKILL.md").is_file():
                continue
            existing = skills.get(directory.name)
            source = directory.resolve()
            if existing is not None and existing != source:
                raise SystemExit(f"Duplicate skill source: {directory.name}")
            skills[directory.name] = source

    if not skills:
        raise SystemExit(f"No shared skills found in {args.source}")
    prune_dangling(target, roots, pathlib.Path(args.backup))
    for name, source in sorted(skills.items()):
        destination = target / name
        if destination.is_symlink() and destination.resolve() == source:
            continue
        if destination.exists() or destination.is_symlink():
            backup(destination, pathlib.Path(args.backup))
        destination.symlink_to(source, target_is_directory=True)


def managed_file(
    target: pathlib.Path,
    body: str,
    backup_root: pathlib.Path,
    force_backup: bool = False,
) -> None:
    if target.is_file() and target.read_text(encoding="utf-8") == body:
        return
    if target.exists() or target.is_symlink():
        old = target.read_text(encoding="utf-8", errors="replace") if target.is_file() else ""
        if force_backup or not any(marker in old for marker in MARKERS):
            backup(target, backup_root)
    target.parent.mkdir(parents=True, exist_ok=True)
    temporary = target.with_name(f".{target.name}.{os.getpid()}.tmp")
    temporary.write_text(body, encoding="utf-8")
    os.chmod(temporary, 0o600)
    os.replace(temporary, target)


def render_agent(args: argparse.Namespace) -> None:
    source = pathlib.Path(args.source)
    target = pathlib.Path(args.target)
    data = tomllib.loads(source.read_text(encoding="utf-8"))
    name = data["name"]
    if name != source.stem:
        raise SystemExit(f"Agent name does not match filename: {source}")
    fields = ["---", f"name: {name}", f"description: {json.dumps(data['description'])}"]
    if args.format == "pi":
        fields.extend((
            "systemPromptMode: append",
            "inheritProjectContext: true",
            "inheritGlobalContext: true",
            "inheritSkills: true",
            "async: true",
        ))
        thinking = data.get("model_reasoning_effort")
        if thinking in {"minimal", "low", "medium", "high", "xhigh", "max"}:
            fields.append(f"thinking: {thinking}")
        if name in {"cleanup-worker", "coding-supervisor", "review-worker"}:
            fields.append("allowNestedSubagents: true")
    elif args.format == "agy":
        fields.extend(("subagent: true", "model: inherit", "commandExecutionPolicy: eager"))
    fields.extend(("---", "", MARKERS[0], "", data["developer_instructions"].strip(), ""))
    managed_file(target, "\n".join(fields), pathlib.Path(args.backup))


def command_metadata(source: pathlib.Path) -> tuple[str, str, str]:
    text = source.read_text(encoding="utf-8")
    match = re.match(r"^---\n(.*?)\n---\n(.*)$", text, re.DOTALL)
    if not match:
        raise SystemExit(f"Missing command frontmatter: {source}")
    frontmatter, body = match.groups()
    description = re.search(r"^description:\s*(.+)$", frontmatter, re.MULTILINE)
    skill = re.search(r"^skill:\s*([a-z0-9-]+)$", frontmatter, re.MULTILINE)
    if not description or not skill or "$ARGUMENTS" not in body:
        raise SystemExit(f"Invalid command metadata or missing argument forwarding: {source}")
    return description.group(1).strip(), skill.group(1), body.strip()


def command_name(name: str, skill: str, output_format: str) -> str:
    reserved = {"init"} if output_format == "gemini" else set()
    if output_format == "claude":
        reserved = {"init", "review", "code-review"}
    if output_format in {"claude", "skill"} and name == skill:
        reserved.add(name)
    return f"harness-{name}" if name in reserved else name


def command_prompt(source: pathlib.Path, output_format: str) -> tuple[str, str, str, str]:
    description, skill, body = command_metadata(source)
    alias = command_name(source.stem, skill, output_format)
    variable = {"pi": "$@", "gemini": "{{args}}"}.get(output_format, "$ARGUMENTS")
    body = body.replace("$ARGUMENTS", variable)
    prefix = f"Load and follow the `{skill}` skill before acting. Preserve the user's arguments."
    return alias, description, skill, f"{prefix}\n\n{body}"


def render_command(args: argparse.Namespace) -> None:
    source = pathlib.Path(args.source)
    target_root = ensure_directory(pathlib.Path(args.target), pathlib.Path(args.backup))
    alias, description, skill, prompt = command_prompt(source, args.format)

    if args.format == "pi":
        body = "\n".join((
            "---", f"description: {json.dumps(description)}", "argument-hint: [arguments]", "---",
            "", MARKERS[0], "", prompt, "",
        ))
        target = target_root / f"{alias}.md"
    elif args.format == "claude":
        body = "\n".join((
            "---", f"name: {alias}", f"description: {json.dumps(description)}",
            "disable-model-invocation: true", "---", "", MARKERS[0], "", prompt, "",
        ))
        target = target_root / alias / "SKILL.md"
    elif args.format == "gemini":
        body = f"description = {json.dumps(description)}\nprompt = {json.dumps(prompt)}\n"
        target = target_root / f"{alias}.toml"
    else:
        body = "\n".join((
            "---", f"name: {alias}", f"description: {json.dumps(description)}", "---",
            "", MARKERS[0], "", prompt.replace("$ARGUMENTS", "the full invocation text"), "",
        ))
        target = target_root / alias / "SKILL.md"
    managed_file(target, body, pathlib.Path(args.backup))


def install_policy(args: argparse.Namespace) -> None:
    base = pathlib.Path(args.source).read_text(encoding="utf-8").strip()
    addon = pathlib.Path(args.addon).read_text(encoding="utf-8").strip() if args.addon else ""
    source = f"{base}\n\n{addon}" if addon else base
    target = pathlib.Path(args.target)
    section = f"{POLICY_START}\n\n{source}\n\n{POLICY_END}"
    current = target.read_text(encoding="utf-8") if target.is_file() else ""
    replace_legacy = False
    if POLICY_START in current and POLICY_END in current:
        start = current.index(POLICY_START)
        end = current.index(POLICY_END, start) + len(POLICY_END)
        prefix = current[:start].rstrip("\r\n")
        suffix = current[end:].strip("\r\n")
        output = "\n\n".join(part for part in (prefix, section, suffix) if part) + "\n"
    elif LEGACY_POLICY_MARKER in current:
        legacy = re.search(rf"(?m)^{re.escape(LEGACY_POLICY_MARKER)}$", current)
        legacy_body = current[legacy.end():] if legacy is not None else ""
        heading = re.search(r"(?m)^# Global Agent Rules[ \t]*$", legacy_body)
        first_heading = re.search(r"(?m)^# (?!#)", legacy_body)
        if (
            legacy is not None
            and heading is not None
            and first_heading is not None
            and first_heading.start() == heading.start()
            and (legacy.start() == 0 or current[legacy.start() - 1] == "\n")
        ):
            global_end = legacy.end() + heading.end()
            after_global = current[global_end:]
            security = re.search(r"(?m)^# Security Rules[ \t]*$", after_global)
            intervening_heading = (
                re.search(r"(?m)^# (?!#)", after_global[:security.start()])
                if security is not None
                else None
            )
            if security is not None and intervening_heading is None:
                security_end = global_end + security.end()
                # A legacy block holds only the shared policy, so its tail is matched against base alone.
                source_security = re.search(r"(?m)^# Security Rules[ \t]*$", base)
                if source_security is None:
                    raise SystemExit("Cannot safely identify the current security policy; existing file left unchanged")
                expected = base[source_security.end():].lstrip("\r\n")
                old_security = current[security_end:]
                old_body = old_security.lstrip("\r\n")
                if not old_body.startswith(expected):
                    raise SystemExit("Cannot safely identify the end of the legacy policy; existing file left unchanged")
                end = security_end + len(old_security) - len(old_body) + len(expected)
                prefix = current[:legacy.start()].rstrip("\r\n")
                suffix = current[end:].strip("\r\n")
                output = "\n\n".join(part for part in (prefix, section, suffix) if part) + "\n"
                replace_legacy = True
            else:
                raise SystemExit("Cannot safely identify the legacy policy boundary; existing file left unchanged")
        else:
            raise SystemExit("Cannot safely identify the legacy policy boundary; existing file left unchanged")
    else:
        output = current.rstrip() + ("\n\n" if current.strip() else "") + section + "\n"
    managed_file(target, output, pathlib.Path(args.backup), force_backup=replace_legacy)


def owns_hook(hook: dict, owner: str = HOOK_OWNER) -> bool:
    command = hook.get("command")
    return isinstance(command, str) and owner in command


def merge_event(event: str, existing: list, groups: list, owner: str = HOOK_OWNER) -> list:
    """Replace this repository's hook entries with `groups`, keeping every user hook and its order.

    The new groups take the place of the first owned entry, even inside a shared group; later owned
    entries are dropped, and with no owned entry the groups are appended.
    """
    merged, placed = [], False
    for group in existing:
        hooks = group.get("hooks") if isinstance(group, dict) else None
        if not isinstance(hooks, list) or not all(isinstance(hook, dict) for hook in hooks):
            raise SystemExit(f"Hooks event {event} must hold groups with a list of hook objects")
        run = []
        for hook in hooks:
            if not owns_hook(hook, owner):
                run.append(hook)
            elif not placed:
                if run:
                    merged.append({**group, "hooks": run})
                    run = []
                merged.extend(groups)
                placed = True
        if run or not hooks:
            merged.append({**group, "hooks": run})
    return merged if placed else merged + groups


def merge_hooks(args: argparse.Namespace) -> None:
    """Put this repository's hook groups in a Codex hooks file, replacing only entries it owns."""
    source = json.loads(pathlib.Path(args.source).read_text(encoding="utf-8"))["hooks"]
    target = pathlib.Path(args.target)
    try:
        current = json.loads(target.read_text(encoding="utf-8")) if target.exists() else {}
    except (OSError, ValueError) as error:
        raise SystemExit(f"Cannot safely parse Codex hooks at {target}: {error}")
    if not isinstance(current, dict) or not isinstance(current.get("hooks", {}), dict):
        raise SystemExit(f"Codex hooks must be an object with a hooks object: {target}")

    current_hooks = current.get("hooks", {})
    hooks = {}
    for event in dict.fromkeys([*current_hooks, *source]):
        existing = current_hooks.get(event, [])
        if not isinstance(existing, list):
            raise SystemExit(f"Codex hooks event must be a list: {event}")
        groups = merge_event(event, existing, source.get(event, []))
        # An event that held only owned entries and is no longer shipped goes away.
        if groups or not existing:
            hooks[event] = groups
    merged = {**current, "hooks": hooks}
    if merged == current:
        return
    managed_file(target, json.dumps(merged, indent=2) + "\n", pathlib.Path(args.backup), force_backup=True)


def catalog_model(catalog: pathlib.Path, harness: str, size: str) -> str:
    """Read `<harness>: <size>: model:` from the model catalog; the catalog owns every model id."""
    in_harness = in_size = False
    for line in catalog.read_text(encoding="utf-8").splitlines():
        if not line.strip() or line.lstrip().startswith("#"):
            continue
        if not line[0].isspace():
            in_harness, in_size = line.rstrip() == f"{harness}:", False
        elif in_harness and re.match(r" {2}\S", line):
            in_size = line.strip() == f"{size}:"
        elif in_harness and in_size:
            match = re.match(r"\s+model:\s*(\S+)\s*$", line)
            if match:
                return match.group(1).strip("'\"")
    raise SystemExit(f"No {harness} {size} model in {catalog}")


def hook_command(script: str) -> str:
    quoted = shlex.quote(script)
    # test skips the hook while its script file is missing
    return f"test ! -f {quoted} || python3 {quoted}"


def merge_claude_settings(args: argparse.Namespace) -> None:
    """Set the Claude settings keys this repository owns, leaving every other key and hook as is."""
    target = pathlib.Path(args.target)
    try:
        current = json.loads(target.read_text(encoding="utf-8")) if target.exists() else {}
    except (OSError, ValueError) as error:
        raise SystemExit(f"Cannot safely parse Claude settings at {target}: {error}")
    if not isinstance(current, dict):
        raise SystemExit(f"Claude settings must be a JSON object: {target}")
    hooks, env = current.get("hooks", {}), current.get("env", {})
    overrides = current.get("skillOverrides")
    overrides = {} if overrides is None else overrides
    if not all(isinstance(value, dict) for value in (hooks, env, overrides)):
        raise SystemExit(f"Claude settings hooks, env, and skillOverrides must be objects: {target}")
    for event in ("PreToolUse", "PostToolUse", "Stop", "SubagentStop"):
        if not isinstance(hooks.get(event, []), list):
            raise SystemExit(f"Claude hooks event must be a list: {event}")

    guard = {
        "matcher": "Agent|Task",
        "hooks": [{"type": "command", "command": hook_command(args.guard)}],
    }
    opus_guard = {
        "matcher": "Read|Bash|mcp__claude-in-chrome__.*|mcp__Claude_Browser__.*|mcp__remote-devices__Claude_Browser__.*|mcp__computer-use__.*",
        "hooks": [{"type": "command", "command": hook_command(args.opus_guard)}],
    }
    ui_hook = {"type": "command", "command": hook_command(args.ui_reminder)}
    ui_post_tool = {"matcher": "Edit|Write|MultiEdit|Bash|Agent|mcp__.*", "hooks": [ui_hook]}
    ui_stop = {"hooks": [ui_hook]}
    model = catalog_model(pathlib.Path(args.catalog), "claude", "medium")
    pre_tool = merge_event("PreToolUse", hooks.get("PreToolUse", []), [guard], GUARD_OWNER)
    pre_tool = merge_event("PreToolUse", pre_tool, [opus_guard], OPUS_OWNER)
    post_tool = merge_event("PostToolUse", hooks.get("PostToolUse", []), [ui_post_tool], UI_OWNER)
    stop = merge_event("Stop", hooks.get("Stop", []), [ui_stop], UI_OWNER)
    subagent_stop = merge_event("SubagentStop", hooks.get("SubagentStop", []), [ui_stop], UI_OWNER)
    merged = {
        **current,
        "autoCompactWindow": COMPACT_WINDOW,
        "timeFormat": "24-hour",
        "timeZone": LOCAL_TZ,
        "env": {
            **env,
            "CLAUDE_CODE_SUBAGENT_MODEL": model,
            "CLAUDE_TIMESTAMPS_TZ": LOCAL_TZ,
            "CLAUDE_TIMESTAMPS_INJECT_CONTEXT": "false",
        },
        "hooks": {
            **hooks,
            "PreToolUse": pre_tool,
            "PostToolUse": post_tool,
            "Stop": stop,
            "SubagentStop": subagent_stop,
        },
        "skillOverrides": {**overrides, **dict.fromkeys(SKILLS_OFF, "off")},
    }
    if merged == current:
        return
    body = json.dumps(merged, indent=2, ensure_ascii=False) + "\n"
    managed_file(target, body, pathlib.Path(args.backup), force_backup=True)


def parser() -> argparse.ArgumentParser:
    root = argparse.ArgumentParser()
    commands = root.add_subparsers(dest="action", required=True)

    skills = commands.add_parser("install-skills")
    skills.add_argument("--source", required=True)
    skills.add_argument("--target", required=True)
    skills.add_argument("--backup", required=True)
    skills.add_argument("--portable", action="append", default=[])
    skills.set_defaults(run=install_skills)

    agent = commands.add_parser("render-agent")
    agent.add_argument("--format", choices=("claude", "pi", "agy"), required=True)
    agent.add_argument("--source", required=True)
    agent.add_argument("--target", required=True)
    agent.add_argument("--backup", required=True)
    agent.set_defaults(run=render_agent)

    command = commands.add_parser("render-command")
    command.add_argument("--format", choices=("claude", "pi", "gemini", "skill"), required=True)
    command.add_argument("--source", required=True)
    command.add_argument("--target", required=True)
    command.add_argument("--backup", required=True)
    command.set_defaults(run=render_command)

    policy = commands.add_parser("install-policy")
    policy.add_argument("--source", required=True)
    policy.add_argument("--target", required=True)
    policy.add_argument("--backup", required=True)
    policy.add_argument("--addon")
    policy.set_defaults(run=install_policy)

    hooks = commands.add_parser("merge-hooks")
    hooks.add_argument("--source", required=True)
    hooks.add_argument("--target", required=True)
    hooks.add_argument("--backup", required=True)
    hooks.set_defaults(run=merge_hooks)

    settings = commands.add_parser("merge-claude-settings")
    settings.add_argument("--target", required=True)
    settings.add_argument("--catalog", required=True)
    settings.add_argument("--guard", required=True)
    settings.add_argument("--opus-guard", required=True)
    settings.add_argument("--ui-reminder", required=True)
    settings.add_argument("--backup", required=True)
    settings.set_defaults(run=merge_claude_settings)
    return root


if __name__ == "__main__":
    arguments = parser().parse_args()
    try:
        arguments.run(arguments)
    except (OSError, ValueError, KeyError) as error:
        print(f"harness-assets: {error}", file=sys.stderr)
        raise SystemExit(1) from error
